{
  "constraints": [
    {
      "constraint": "图像中的讴歌标识主体应呈现为字母“A”的卡钳造型，而不是普通印刷体字母或单纯文字。",
      "polarity": "must_have",
      "variants": [],
      "source": "desc"
    },
    {
      "constraint": "该“A”形卡钳主体应包含两条在顶部交汇的斜向边和一条横向连接，形成可辨认的夹钳轮廓。",
      "polarity": "must_have",
      "variants": [],
      "source": "desc"
    },
    {
      "constraint": "图像中不得将本田“H”形标志作为讴歌标识主体。",
      "polarity": "must_not_have",
      "variants": [],
      "source": "common_sense"
    },
    {
      "constraint": "图像中不得将雷克萨斯、英菲尼迪等其他豪华品牌的椭圆或字母标志作为讴歌标识主体。",
      "polarity": "must_not_have",
      "variants": [],
      "source": "common_sense"
    },
    {
      "constraint": "图像不得仅以“讴歌”或“ACURA”文字作为唯一主体而缺少卡钳形A徽标。",
      "polarity": "must_not_have",
      "variants": [],
      "source": "desc"
    }
  ]
}
